def unique_key_value_pairs(data: list[tuple[str, int]]) -> dict[str, int]:
    """Convert a list of (key, value) tuples into a dictionary, keeping the last occurrence of duplicate keys. Edge case: empty list returns empty dict."""
    result: dict[str, int] = {}
    for key, value in data:
        result[key] = value
    return result
