def word_reverse_map(text: str) -> dict:
    """Maps each contiguous sequence of alphanumeric characters to its reverse.

    Args:
        text: A string containing alphabetic and numeric characters.

    Returns:
        A dictionary where keys are the original words and values are their reversed forms.
        Non-alphanumeric characters act as delimiters and are ignored (not included in keys).
        Empty strings or non-alphanumeric-only input results in an empty dictionary.
    """
    result = {}
    current = []
    for char in text:
        if char.isalnum():
            current.append(char)
        else:
            if current:
                result[''.join(current)] = ''.join(reversed(current))
                current = []
    if current:
        result[''.join(current)] = ''.join(reversed(current))
    return result

