from collections import deque

def bfs_pathfinder(start: int, end: int, graph: dict[int, list[int]]) -> list[int]:
    if start == end:
        return [start]
    visited = {start}
    queue = deque([start])
    path_map = {start: [start]}

    while queue:
        node = queue.popleft()
        if node == end:
            return path_map[node]

        if node in graph:
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    new_path = path_map[node] + [neighbor]
                    path_map[neighbor] = new_path
                    queue.append(neighbor)

    return []
```

