def aggregate_stats(data: list[int]) -> dict[str, int]:
    if not data:
        return {"count": 0, "sum": 0, "min": 0, "max": 0}
    count = len(data)
    total = sum(data)
    minimum = min(data)
    maximum = max(data)
    return {"count": count, "sum": total, "min": minimum, "max": maximum}
